div.alphabet{clear:both;position:relative;margin-bottom:2rem}.dataTables_length{margin-bottom:1rem}@media screen and (max-width:640px){div.alphabet{text-align:center}}div.alphabet ul{display:inline-block;margin:0;padding:0;list-style:none}div.alphabet li{display:inline-block}div.alphabet a{display:inline-block;cursor:pointer;text-align:center;text-decoration:none;box-sizing:content-box;padding:.2em .1em;min-width:1.3em;border-radius:2px;color:#333 !important;border:1px solid #979797;margin-right:.5rem;background-color:#fff}div.alphabet a:hover{color:#fff !important;border:1px solid #a5221e;background-color:#a5221e}div.alphabet a:active{outline:none;background-color:#a5221e;box-shadow:inset 0 0 3px #111}div.alphabet a.empty{color:#888 !important}div.alphabet a.active,div.alphabet a.active.empty{color:#fff !important;border:1px solid #a5221e;background-color:#a5221e}div.alphabet .alphabet-info-display{margin-right:.5em}div.alphabet div.alphabet-info{position:absolute;margin-top:.2em;padding:.2em .4em;text-align:center;opacity:0;z-index:9999}tr.alphabet-group,tr.alphabet-group:hover{background-color:rgba(0,0,0,.15) !important}